CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(80) PRIMARY KEY, value LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('admin','staff') NOT NULL DEFAULT 'staff', active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, slug VARCHAR(100) NOT NULL UNIQUE, icon VARCHAR(40) NOT NULL DEFAULT 'headphones', sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, brand VARCHAR(80) NOT NULL, description TEXT NOT NULL, images LONGTEXT NOT NULL, active TINYINT NOT NULL DEFAULT 1, featured TINYINT NOT NULL DEFAULT 0, pinned TINYINT NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0, flash_price BIGINT NULL, flash_start DATETIME NULL, flash_end DATETIME NULL, created_at DATETIME NOT NULL, FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS variants (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, product_id BIGINT UNSIGNED NOT NULL, sku VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, price BIGINT NOT NULL, cost BIGINT NOT NULL, stock INT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, version INT NOT NULL DEFAULT 1, FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS coupons (code VARCHAR(40) PRIMARY KEY, type ENUM('fixed','percent') NOT NULL, value BIGINT NOT NULL, min_total BIGINT NOT NULL DEFAULT 0, max_discount BIGINT NULL, max_uses INT NOT NULL DEFAULT 100, uses INT NOT NULL DEFAULT 0, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, token_hash CHAR(64) NOT NULL UNIQUE, token_cipher TEXT NOT NULL, lookup_code VARCHAR(24) NOT NULL UNIQUE, idempotency_key CHAR(64) NOT NULL UNIQUE, customer_name VARCHAR(120) NOT NULL, phone VARCHAR(20) NOT NULL, address TEXT NOT NULL, region VARCHAR(180) NOT NULL, note TEXT NOT NULL, latitude DECIMAL(10,7) NULL, longitude DECIMAL(10,7) NULL, status VARCHAR(30) NOT NULL DEFAULT 'received', payment_status VARCHAR(30) NOT NULL DEFAULT 'pending', payment_method VARCHAR(20) NOT NULL, subtotal BIGINT NOT NULL, discount BIGINT NOT NULL, shipping_fee BIGINT NULL, distance_km DECIMAL(10,3) NULL, shipping_status VARCHAR(25) NOT NULL, shipping_snapshot LONGTEXT NOT NULL, store_snapshot LONGTEXT NOT NULL, payment_snapshot LONGTEXT NOT NULL, total BIGINT NULL, coupon_code VARCHAR(40) NULL, actual_shipping BIGINT NOT NULL DEFAULT 0, other_cost BIGINT NOT NULL DEFAULT 0, paid_amount BIGINT NOT NULL DEFAULT 0, refunded_amount BIGINT NOT NULL DEFAULT 0, shipping_reversed BIGINT NOT NULL DEFAULT 0, internal_note TEXT NOT NULL, cancel_reason TEXT NULL, stock_released TINYINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, INDEX(created_at), INDEX(phone), INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, product_name VARCHAR(180) NOT NULL, variant_name VARCHAR(100) NOT NULL, sku VARCHAR(80) NOT NULL, image VARCHAR(500) NOT NULL, quantity INT NOT NULL, unit_price BIGINT NOT NULL, unit_cost BIGINT NOT NULL, discount BIGINT NOT NULL DEFAULT 0, returned_quantity INT NOT NULL DEFAULT 0, revenue_reversed BIGINT NOT NULL DEFAULT 0, cost_reversed BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(variant_id) REFERENCES variants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NULL, actor VARCHAR(120) NOT NULL, channel VARCHAR(20) NOT NULL, action VARCHAR(80) NOT NULL, detail LONGTEXT NOT NULL, created_at DATETIME NOT NULL, INDEX(order_id), FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS inventory_moves (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, variant_id BIGINT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NULL, delta INT NOT NULL, reason VARCHAR(60) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(variant_id) REFERENCES variants(id), FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS refunds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, amount BIGINT NOT NULL, item_id BIGINT UNSIGNED NULL, quantity INT NOT NULL DEFAULT 0, reason TEXT NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, attempts INT NOT NULL DEFAULT 0, state VARCHAR(20) NOT NULL DEFAULT 'pending', last_error TEXT NULL, next_attempt DATETIME NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rate_limits (bucket CHAR(64) PRIMARY KEY, hits INT NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS telegram_updates (update_id BIGINT PRIMARY KEY, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS telegram_pending (nonce CHAR(32) PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, user_id VARCHAR(30) NOT NULL, chat_id VARCHAR(30) NOT NULL, action VARCHAR(40) NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS order_actions (idempotency_key CHAR(64) PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS checkout_keys (idempotency_key CHAR(64) PRIMARY KEY, created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
